package worlds.content

import androidx.test.ext.junit.runners.AndroidJUnit4
import androidx.test.platform.app.InstrumentationRegistry
import org.json.JSONObject
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertTrue
import org.junit.Test
import org.junit.runner.RunWith
import java.util.UUID

@RunWith(AndroidJUnit4::class)
class SpreadsheetEngineTest {
    private val context get() = InstrumentationRegistry.getInstrumentation().targetContext
    /** Generated by the real desktop engine, with the display it computed for every cell. */
    private fun fixture() = JSONObject(InstrumentationRegistry.getInstrumentation().context.assets.open("spreadsheet-desktop.json").bufferedReader().use { it.readText() })

    @Test fun everyFormulaMatchesTheDesktopEngine() {
        val fixture = fixture()
        val workbook = SpreadsheetEditing.workbook(JSONObject().put("sheet", fixture.getJSONObject("workbook")).toString())
        val actual = SpreadsheetEvaluator(workbook).evaluate()
        val expected = fixture.getJSONObject("expected")
        val mismatches = ArrayList<String>()
        expected.keys().forEach { sheet ->
            val cells = expected.getJSONObject(sheet)
            cells.keys().forEach { key ->
                val want = cells.getString(key)
                val got = actual[sheet]?.get(key)?.display
                if (want != got) mismatches.add("$sheet!$key expected <$want> got <$got>")
            }
        }
        assertEquals(mismatches.joinToString("\n"), 0, mismatches.size)
    }

    @Test fun editingKeepsDesktopOnlyFields() {
        val fixture = fixture()
        val metadata = JSONObject().put("other", "kept").put("sheet", fixture.getJSONObject("workbook")).toString()
        val workbook = SpreadsheetEditing.workbook(metadata)
        val sheet = SpreadsheetEditing.activeSheet(workbook)
        SpreadsheetEditing.setCell(sheet, "F1", "42")
        SpreadsheetEditing.setCell(sheet, "A8", "")
        val merged = JSONObject(SpreadsheetEditing.merge(metadata, workbook.toString()))
        assertEquals("kept", merged.getString("other"))
        val saved = merged.getJSONObject("sheet").getJSONArray("sheets").getJSONObject(0)
        assertEquals("42", saved.getJSONObject("cells").getJSONObject("F1").getString("v"))
        assertEquals("integer", saved.getJSONObject("cells").getJSONObject("F1").getJSONObject("s").getString("format"))
        assertFalse(saved.getJSONObject("cells").has("A8"))
        assertEquals(1, saved.getInt("frozenRows"))
        assertEquals(1, saved.getJSONArray("merges").length())
        assertEquals(1, saved.getJSONArray("conditionalRules").length())
        assertEquals(140, saved.getJSONObject("colWidths").getInt("0"))
    }

    @Test fun newSheetsStartEmptyWithDesktopDefaults() {
        val workbook = SpreadsheetEditing.workbook("{}")
        val sheet = SpreadsheetEditing.activeSheet(workbook)
        assertEquals("Sheet 1", sheet.getString("name"))
        assertEquals(60, sheet.getInt("rows"))
        assertEquals(26, sheet.getInt("cols"))
        assertEquals(0, sheet.getJSONObject("cells").length())
    }

    @Test fun addedSheetsGetUnusedNames() {
        val workbook = SpreadsheetEditing.newWorkbook()
        assertEquals("Sheet 2", SpreadsheetEditing.addSheet(workbook).getString("name"))
        assertEquals("Sheet 3", SpreadsheetEditing.addSheet(workbook).getString("name"))
        assertEquals(workbook.getString("activeSheetId"), SpreadsheetEditing.sheets(workbook).last().getString("id"))
    }

    @Test fun workbookIsStoredInResourceMetadata() {
        val database = "sheet-${UUID.randomUUID()}.db"
        try {
            ContentStore(context, database).use { store ->
                val sheetResource = store.create("spreadsheet", "Budget", metadata = """{"keep":1}""")
                val workbook = SpreadsheetEditing.workbook(sheetResource.metadata)
                SpreadsheetEditing.setCell(SpreadsheetEditing.activeSheet(workbook), "B2", "=1+1")
                val saved = store.saveWorkbook(sheetResource.id, workbook.toString())
                assertTrue(saved.revision > sheetResource.revision)
                val reloaded = store.load(sheetResource.id)
                assertNotNull(reloaded)
                val metadata = JSONObject(reloaded!!.resource.metadata)
                assertEquals(1, metadata.getInt("keep"))
                val again = SpreadsheetEditing.workbook(reloaded.resource.metadata)
                assertEquals("=1+1", SpreadsheetEditing.rawValue(SpreadsheetEditing.activeSheet(again), "B2"))
            }
        } finally { context.deleteDatabase(database) }
    }
}
